L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_DESC_UNIT_GET_1044"
L10_1 = "시청자 여러분, 그러니까 응, 미하~ 저, 오늘부터 이 회사에서 일하게 됐는데요... 잘할 수 있을지 지켜 봐 주시면... 앗... 그, 사장님, 구독자 미션인데... 잠깐 같이 카메라 좀 봐 주시면 안 될까요...?"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_DESC_UNIT_GET_1045"
L11_1 = "안냥~♪ 하트베리의 메인댄서, 보미야~♪ 그렇게 기대 만빵인 표정으로 반겨 줘서 무지 고마워! 그럼 다음 얘기는 낮잠 푹 자고 하는 걸루다가!"
L9_1[1] = L10_1
L9_1[2] = L11_1
