L14_1 = "클로디아 넬슨. 성무의 집행을 위해 파견되었습니다. 오늘부터 자비로우신 주님의 은총 아래, 사장님과 함께 할게요."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_DESC_UNIT_GET_1049"
L15_1 = "Hello~ 에이미 스트릭랜드입니다! 그런데 혹시 프리덤 라이더라고 들어보셨나요? 네? 모르신다고요......?"
L13_1[1] = L14_1
L13_1[2] = L15_1
