L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_DESC_UNIT_GET_1068"
L29_1 = "독립형 제어시스템 이오 활성화. 통합지휘통신망 연결 성공. 교리에 의거하여 ACT49S 이프리트 보병전차의 기동을 재개합니다. 전황 통제를 위해 운용해 주십시오."
