L29_1 = {}
L30_1 = "SI_DESC_UNIT_GET_1070"
L31_1 = "독립형 제어시스템 이오 활성화. 통합지휘통신망 연결 성공. 교리에 의거하여 ACT52L 에스타크 자주곡사포의 기동을 재개합니다. 초장거리 화력 지원에 투입해 주십시오."
L29_1[1] = L30_1
