L41_1 = {}
L42_1 = "SI_DESC_UNIT_GET_1085"
L43_1 = "그대가 이곳의 지도자인가. 좋다. 이 자리에서 맹세하지. 나 에스테로사 드 슈발리에는 무고한 이들을 지키기 위해, 그대의 검이 되어 적에 맞서겠다."
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_DESC_UNIT_GET_1086"
L44_1 = "조디악 나이츠의 견습 단원, 양한솔입니다. 선배님들께 부끄럽지 않은 후배가 되도록 열심히 하겠습니다!"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_DESC_UNIT_GET_1087"
L45_1 = "에리어스라고 해요. 갑작스러우시겠지만... 길을 잃어버려서요. 혹시 저희 단장님께 연락해 주시겠어요? 저번처럼 혼자 화물선에 탔을까 봐 걱정하고 있을 거에요."
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_DESC_UNIT_GET_1088"
L46_1 = "조디악 나이츠의 전갈, 피오네 로웰이 참전하겠습니다. 기사단의 긍지에 걸맞은 무훈을 보여 드리죠."
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_DESC_UNIT_GET_1089"
L47_1 = "리브 앨런이야, 사장님! 조디악 나이츠에서는 천칭자리를 대표하고 있지만, 그런 건 아무래도 좋잖아? 그래도 나 보기보다 굉장하니까, 일단 믿어 보라고! 헤헷♪"
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_DESC_UNIT_GET_1090"
L48_1 = "유나 스프링필드야. 코스프레 같아도 일단은 어엿한 마녀 지망생이라구!"
