L8_1 = "SI_DESC_UNIT_GET_1109"
L9_1 = "흐흥. 채용이라... 이런 제안은 처음이군. 뭐, 나를 부른 배짱을 높이 사서 당분간은 놀아 주지."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_DESC_UNIT_GET_1110"
L10_1 = "프레데릭 도마, 여기 대령했습니다. 누군가의 은밀한 비밀을 파헤치고 싶다면 저에게 말씀해 주시죠."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_DESC_UNIT_GET_1111"
L11_1 = "부탁할 게 있다고? 잘 됐네. 마침 주먹 쓸 상대가 필요하던 참이었거든."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_DESC_UNIT_GET_1112"
L12_1 = "저와 인연이 닿은 분이...... 당신이셨군요. 바람을 따라 이곳에 당도했습니다. 나나하라 가문의 당주로서, 인사 올립니다."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_DESC_UNIT_GET_1113"
L13_1 = "언니…… 아니, 당주님께 말씀은 들었습니다. 나나하라류 제1사범, 나나하라 치후유. 당신의 적을 베어드리겠습니다."
