L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_DESC_UNIT_GET_1114"
L14_1 = "아르바이트를 구하신다면서요? 적당히 평범한 고등학생이라도 상관없나요?"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_DESC_UNIT_GET_1115"
L15_1 = "주인어른께 인사 올리옵니다. 가문의 이름에 누를 끼치는 일 없도록, 성심성의껏 시중들겠습니다."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_DESC_UNIT_GET_1116"
L16_1 = "후후, 나로 말할 것 같으면 가문 연합을 어둠 속에서 지배하는 흑막 중의 흑막! 오오가미 님이시다! ...뭐? 본명이냐고? 어…… 당연하지!"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_DESC_UNIT_GET_1117"
L17_1 = "로이라고 불러. 미안한데 잠깐 신세 좀 질게. 뭐, 시비 거는 녀석만 없으면 얌전하게 지낼 테지만."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_DESC_UNIT_GET_1118"
L18_1 = "프리드웬 기관장, 엘리자베스 펜드래건이랍니다. 귀하께서 이 회사의 대표시군요. 환대해 주셔서 감사하지만... 피차 바쁜 입장이니 티타임은 다음을 기약하기로 하죠."
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_DESC_UNIT_GET_1119"
L19_1 = "라이언 페리어, 인사드립니다. 편하신 대로 불러 주십시오. 앞으로 이 주먹은 당신을 위해 쓰겠습니다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_DESC_UNIT_GET_1120"
L20_1 = "모건, 새디어스 모건일세. 자질구레한 일을 처리해 주는 해결사지. 함께 잘해 보세나."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_DESC_UNIT_GET_1121"
L21_1 = "처음 뵙겠습니다, 사장님. 알파트릭스 이노베이션의 리더 신지아라고 해요. 갑작스러우시겠지만, 저와 친구가 되어 주시면 안 될까요?"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_DESC_UNIT_GET_1122"
L22_1 = "대 침식전을 선도하는 알파트릭스 이노베이션. 그리고 전 초원이에요. 김씨라고 부르셔도 상관없지만요."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_DESC_UNIT_GET_1123"
L23_1 = "세상의 악을 멸하기 위해 나타난 파사의 심판자, 가브리엘 준 더 비셔스 브레이커. 이제 그대와 함께하겠다! 빠밤."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_DESC_UNIT_GET_1124"
L24_1 = "대 침식전을 선도하는 알파트릭스 이노베이션이 당신을 응원합니다. 후훗, 많이 상투적인 문구죠? 하지만 실망하시기엔 일러요. 제 실력은 상투적이지 않거든요."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_DESC_UNIT_GET_1125"
L25_1 = "악당은 아닌 것 같으니까, 이 오새롬이 같이 싸워 줄게! 아 참, 난 알파트릭스 소속이야. 일단 기억해 둬."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_DESC_UNIT_GET_1126"
L26_1 = "장기 고용 의뢰를 넣었던데. 무리해야 하는 건 알고 있으니까, 합리적인 지시만 바랄게."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_DESC_UNIT_GET_1127"
L27_1 = "반가워요, 사장님. 뭐부터 터뜨릴까요?"
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_DESC_UNIT_GET_1128"
L28_1 = "거슬리는 녀석이 있으면 얘기해. 잘 타일러 줄 테니까."
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
L28_1 = "SI_DESC_UNIT_GET_1129"
L29_1 = "박현수요. 잘해 봅시다, 사장님. 서로 야근하는 일 없게."
