L30_1 = {}
L31_1 = "SI_DESC_UNIT_GET_1132"
L32_1 = "제나 버드, 관리국 직속 카운터 소대인 오피셜 서포트의 소대장입니다! 귀사의 성공을 지원하라는 지시를 받고 파견되었습니다. 잘 부탁드립니다, 사장님!"
L30_1[1] = L31_1
L30_1[2] = L32_1
L31_1 = {}
L32_1 = "SI_DESC_UNIT_GET_1133"
L33_1 = "사건의 냄새가 풍기네요. 즐거운 파견이 되겠어요."
L31_1[1] = L32_1
L31_1[2] = L33_1
L32_1 = {}
L33_1 = "SI_DESC_UNIT_GET_1134"
L34_1 = "오피셜 서포트의 귀염둥이 마스코트, 아이리님 등장이야~♪"
L32_1[1] = L33_1
L32_1[2] = L34_1
L33_1 = {}
L34_1 = "SI_DESC_UNIT_GET_1135"
L35_1 = "세상의 질서와 평화를 위해! 열심히 싸울게요! 뭐부터 시작할까요? 불우이웃돕기? 아니면 유기견 구조?"
L33_1[1] = L34_1
L33_1[2] = L35_1
L34_1 = {}
L35_1 = "SI_DESC_UNIT_GET_1136"
L36_1 = "한소림이다. 이 바닥에서는 심판의 방아쇠라는 별명으로 통하지. 원한다면 본관을 그렇게 불러도... 기다려. 그 토끼는 그냥 토끼가 아니라 스미스 병장이다. 함부로 만지면 호되게... 흐그그, 마, 만지지 말아 주세요... 한정품이란 말이에요..."
L34_1[1] = L35_1
L34_1[2] = L36_1
L35_1 = {}
L36_1 = "SI_DESC_UNIT_GET_1137"
L37_1 = "조호진이라고 합니다. 딱히 장기 같은 건 없지만, 잘 부탁드려요."
L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_DESC_UNIT_GET_1138"
L38_1 = "주시영이에요. 그냥 평범한 용병이니까 특별히 기억해 두실 거 없어요."
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_DESC_UNIT_GET_1139"
L39_1 = "델타 세븐 내사과의 카린 웡이에요. 실례지만 귀사의 재무제표와 회의록, 데이터베이스 접근 권한을 주실 수 있을까요?"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_DESC_UNIT_GET_1142"
L40_1 = "용병, 에디다. 앞으로의 처우에 대해 얘기를 좀 나누고 싶군."
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_DESC_UNIT_GET_1143"
L41_1 = "안녕, 사장님. 제시카라고 합니다. 별다른 조건은 없고 일한 만큼만 챙겨 주면 좋겠네요."
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_DESC_UNIT_GET_1144"
L42_1 = "여, 사장님! 찰리라고 불러 줘! 우리 같이 한몫 제대로 잡아 보자고!"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_DESC_UNIT_GET_1145"
L43_1 = "최고가 뭔지 아는 사장님이구만! 우리 정도의 베테랑을 고용하다니! 사업 번창은 따놓은 당상이지, 암!"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_DESC_UNIT_GET_1146"
L44_1 = "서 있는 장소가 달라져도, 군인이 할 일은 변함없다."
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
L44_1 = "SI_DESC_UNIT_GET_1147"
L45_1 = "이런 멋진 곳에 저희들을 초대해 주셔서 고마워요. 그런데 오는 동안 허기가 져서... 만찬부터 시작하면 안 될까요?"
L43_1[1] = L44_1
L43_1[2] = L45_1
L44_1 = {}
L45_1 = "SI_DESC_UNIT_GET_1148"
L46_1 = "쇠꼬챙이 도착했습니다~ 말귀 못 알아듣는 녀석들 귓구멍 뚫어 주기에 안성맞춤이야!"
L44_1[1] = L45_1
L44_1[2] = L46_1
L45_1 = {}
L46_1 = "SI_DESC_UNIT_GET_1149"
L47_1 = "가문의 명예를 걸고 귀사의 번영에 헌신하겠습니다. 사무실이 조금 추워지겠지만, 양해해 주시길."
L45_1[1] = L46_1
L45_1[2] = L47_1
L46_1 = {}
L47_1 = "SI_DESC_UNIT_GET_1150"
L48_1 = "준비는 끝났다. 출격 지시를 기다리고 있어."
L46_1[1] = L47_1
L46_1[2] = L48_1
L47_1 = {}
L48_1 = "SI_DESC_UNIT_GET_1151"
L49_1 = "오는 길에 지도가 필요한 학생들이 많이 보이더군요. 아카데미의 귀감으로서 성실히 가르치겠어요."
L47_1[1] = L48_1
L47_1[2] = L49_1
L48_1 = {}
L49_1 = "SI_DESC_UNIT_GET_1152"
L50_1 = "학생회 선도위원… 이었던가? 아무튼 잘 부탁해, 보스."
L48_1[1] = L49_1
L48_1[2] = L50_1
L49_1 = {}
L50_1 = "SI_DESC_UNIT_GET_1154"
L51_1 = "내가 왔으니 걱정 마. 확실하게 지켜줄게. 아 뭐, 기왕이면 보수도 잘 챙겨주는 편이 더 분발하겠지만?"
L49_1[1] = L50_1
L49_1[2] = L51_1
L50_1 = {}
L51_1 = "SI_DESC_UNIT_GET_1155"
L52_1 = "완전무결 전천후 대응 전략 병기, A.K.A 야누스, 출격 준비를 마치고 대기 중."
L50_1[1] = L51_1
L50_1[2] = L52_1
