L1_1 = {}
L2_1 = "SI_DESC_UNIT_GET_1157"
L3_1 = "이 그리운 향기는... 현실의 것인가. 마침내 돌아왔군."
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_DESC_UNIT_GET_1158"
L4_1 = "애들 관리하기 힘들다고? 그럼 내가 도와 줘야겠네?"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_DESC_UNIT_GET_1159"
L5_1 = "이 복장은 오랜만이군요. 이수연, 출격 대기 중입니다."
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_DESC_UNIT_GET_1160"
L6_1 = "오오, 이제부터 같이 노는 거야? 뭔진 몰라도 재밌겠다! 할래, 할래!"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_DESC_UNIT_GET_1161"
L7_1 = "솔라 코덱스 세트 온! 견습 대마녀 유나 스프링필드, 지금 출격합니다!"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_DESC_UNIT_GET_1162"
L8_1 = "플로라 메이드 서비스를 이용해 주셔서 감사합니다, 주인님. 메이드장으로서 혼신을 다해 모시겠습니다."
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_DESC_UNIT_GET_1163"
L9_1 = "주방 담당, 리코리스야. 날 고용할 거면 마음 단단히 먹으라고."
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_DESC_UNIT_GET_1164"
L10_1 = "견습 메이드 모네 도착했슴다! 주인님을 만나서 무지 기쁘지 말임다!"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_DESC_UNIT_GET_1165"
L11_1 = "주인님의 숙면을 책임질 릴리라고 합니다. 레전드를 찍어 드리죠. ...이렇게 쓰는 말 아니었나요?"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_DESC_UNIT_GET"
L12_1 = "NICETOMEETYOU"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_DESC_UNIT_GET_12001"
L13_1 = "하여간 내가 없으면 회사가 안 굴러간다니까."
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_DESC_UNIT_GET_12002"
L14_1 = "돈을. 벌어. 와라."
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_DESC_UNIT_GET_20001"
L15_1 = "관리 실패 직후부터 운용된 구형 강습함. 낮은 카탈로그 스펙에 비해 실전에서의 활약은 우수하다고 한다."
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_DESC_UNIT_GET_20002"
L16_1 = "태스크포스 업계에서 사랑받는 강습함. 강습함에 요구하는 최소 성능을 만족하면서 신뢰성이 높다."
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_DESC_UNIT_GET_20003"
L17_1 = "프랑스 정규군이 운용 중인 제식 순양함. 탁월한 기동성으로 측면 공세에서 우위를 점한다."
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_DESC_UNIT_GET_20004"
L18_1 = "차세대 고속 순양함. 강력한 지휘통제 능력을 갖춰 현장 대원의 교전 효율 향상에 일조한다. "
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_DESC_UNIT_GET_20005"
L19_1 = "노르망디급 중장갑함. 화력 지원 능력과 자가 수리 시설을 탑재한 중장갑함의 모범이다."
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_DESC_UNIT_GET_20006"
L20_1 = "미 합중국이 비밀리에 건조한 3세대 중장갑함. 적의 공격으로부터 아군의 인적 자원을 보호하는 데 특화되어 있다."
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_DESC_UNIT_GET_20007"
L21_1 = "이면세계의 기상을 연구하기 위해 건조되었던 구형 특무함. 인위적인 기상 현상을 발생시킬 수 있다."
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_DESC_UNIT_GET_20008"
L22_1 = "이면세계의 생태를 연구하기 위해 건조된 특무함. 연구용 나노 머신을 살포하여 전투 지원이 가능하다."
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_DESC_UNIT_GET_20009"
L23_1 = "대반격 초기부터 건조된 구형 강습함. 성능은 평균 이하이지만, 저렴한 가격 덕분에 가장 많이 건조된 함급이다."
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_DESC_UNIT_GET_20010"
L24_1 = "독일에서 건조된 바이에른급 중장갑함. 적의 핵심만을 제거하는 정밀타격전에 특화되어 있다."
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_DESC_UNIT_GET_20011"
L25_1 = "기갑 전력을 지원하는 데 특화된 강습함. 적합한 병종을 편제하면 놀라운 효율을 자랑한다."
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_DESC_UNIT_GET_20012"
L26_1 = "보병 전력을 지원하는 데 특화된 순양함. 주로 함종 특유의 기동성을 발휘하여 거점 장악에 사용한다."
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_DESC_UNIT_GET_20014"
L27_1 = "신형 동력기관을 탑재한 순양함. 차별화된 정보 처리 능력으로 적의 취약점을 분석하는 한편, 동력기관이 발생시키는 돌풍으로 공수 양면에 기여한다."
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_DESC_UNIT_GET_20015"
L28_1 = "생존성에 중점을 둔 강습함. 직렬식 동력기관에서 비롯된 고출력으로 통상의 3배에 달하는 위상 장벽을 생성한다."
L26_1[1] = L27_1
L26_1[2] = L28_1
