L5_1 = "SI_DESC_UNIT_GET_21031"
L6_1 = "인기 애니메이션 강습! 브레멘 동물전대에 등장하는 우주 악당 사천왕 중 하나인 캡틴 바르바로사. 탐욕스럽고 냉혈한이지만 물을 무서워한다."
L4_1[1] = L5_1
