L7_1 = "인기 애니메이션 강습! 브레멘 동물전대에 등장하는 분홍 발바닥 공수부대 출신 탐탐. 명예 퇴직 후 우주를 떠돌다가 대나무 맛에 반해 숲에 정착한다."
