L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_DESC_UNIT_GET_21041"
L10_1 = "함선을 강제로 인양하고 약탈하기 위해 스캐빈저가 오랫동안 개조한 함선. 내부의 강화 시설을 통해 전투원의 취약점을 제거하는 시술과 개조가 이뤄진다."
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_DESC_UNIT_GET_104203"
L11_1 = "새로운 의상을 준비해 주셔서 고마워요. 하트베리 가은, 행복의 전령으로 분발하겠습니다. 부끄러워 죽겠지만요."
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_DESC_UNIT_GET_100505"
L12_1 = "뭐, 뭔데. 고양이랑 노는 사람 처음 봐? 이 녀석들, 오냐오냐해 줬더니 이젠 여기가 아주 자기들 놀이턴 줄 안다니까... 거추장스럽게시리."
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
