L27_1[1] = L28_1
L27_1[2] = L29_1
L28_1 = {}
L29_1 = "SI_DESC_UNIT_GET_114715"
L30_1 = "이런 멋진 곳에 저희들을 초대해 주셔서 고마워요. 그런데 오는 동안 허기가 져서... 만찬부터 시작하면 안 될까요?"
L28_1[1] = L29_1
L28_1[2] = L30_1
L29_1 = {}
L30_1 = "SI_DESC_UNIT_GET_113615"
L31_1 = "한소림이다. 이 바닥에서는 심판의 방아쇠라는 별명으로 통하지. 원한다면 본관을 그렇게 불러도... 기다려. 그 토끼는 그냥 토끼가 아니라 스미스 병장이다. 함부로 만지면 호되게... 흐그그, 마, 만지지 말아 주세요... 한정품이란 말이에요..."
L29_1[1] = L30_1
L29_1[2] = L31_1
L30_1 = {}
