L2_1 = "SI_DESC_UNIT_GET_21045"
L3_1 = "엘리시움 필하모닉의 세계에서 설계했던 함선을 원형에 가깝게 복원한 형태. 독자적인 파동 제어 기술체계로 최적의 연주 환경을 조성한다."
