L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_DESC_UNIT_GET_32201"
L4_1 = "도시는 밤에도 밝네요! 우리 모네가 칭찬했던 도시의 풍경이란 게 바로 이런 건가 봐요. 참! 딸 보러 온 김에 잠시 머물다 가려고 하는데, 가이드 좀 부탁드려도 될까요?"
